        "\n",
        "# Define external global data for 12 steps\n",
        "global_data_for_12_steps = [\n",
        "    {'inflation_rate': 0.05, 'weather_condition': 'normal', 'tax_rate': 0.15, 'market_sentiment': 0.5},\n",
